let cur = 'en';
export function setLang(l) { cur = D[l] ? l : 'en'; return cur; }
export function getLang() { return cur; }
export function t(key, vars) {
  let s = D[cur][key] ?? D.en[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return s;
}
